##' Carrier for the alignment data as geom_msa() saw it, before any layer
##' cropped it. Stored on the plot so that other layers can derive their own
##' data without reaching into plot$layers[[1]] (#75, #76).
##'
##' @param data sequence alignment data generated by msa_data().
##' @noRd
msa_source <- function(data) {
    structure(list(data = data), class = "msa_source")
}

##' @method ggplot_add msa_source
##' @export
ggplot_add.msa_source <- function(object, plot, ...) {
    plot$ggmsa_data <- object$data
    plot
}

##' @noRd
msa_source_data <- function(plot) {
    if (is.null(plot$ggmsa_data)) {
        panel <- msa_panel(plot)
        if (!is.null(panel)) {
            return(plot[[panel]]$ggmsa_data)
        }
        return(plot$layers[[1]]$data)
    }
    plot$ggmsa_data
}

##' geom_msaBar() stacks the alignment and the conservation bar into a
##' patchwork, after which the alignment lives in one of the panels rather than
##' on the plot itself.  Returns that panel, or NULL if `plot` is not a stack
##' built by ggmsa (#49).
##'
##' @noRd
msa_panel <- function(plot) {
    if (!inherits(plot, "patchwork")) {
        return(NULL)
    }
    holds <- vapply(seq_along(plot), function(i) {
        panel <- plot[[i]]
        inherits(panel, "gg") && is.data.frame(panel$ggmsa_data)
    }, logical(1))
    if (!any(holds)) {
        return(NULL)
    }
    which(holds)[1]
}

##' @noRd
msa_add <- function(plot, object, ...) {
    panel <- msa_panel(plot)
    if (is.null(panel)) {
        return(ggplot_add(object, plot, ...))
    }
    plot[[panel]] <- ggplot_add(object, plot[[panel]], ...)
    plot
}

##' @method ggplot_add seqlogo
##' @export
ggplot_add.seqlogo <- function(object, plot, ...) {
    msaData <- msa_source_data(plot)
    logo_tidyData <- msa2tidy(msaData)
    logo_font <- object$font
    logo_color <- object[["color"]]
    adaptive <- object$adaptive
    top <- object$top
    logo_custom_color <- object[["custom_color"]]
    show.legend <- object$show.legend

    ly_logo <- geom_logo(data  = logo_tidyData, 
                         font = logo_font, 
                         color = logo_color,
                         adaptive = adaptive, 
                         top = top, 
                         custom_color = logo_custom_color, 
                         show.legend = show.legend)
    msa_add(plot, ly_logo, ...)
}

##' @method ggplot_add seed
##' @export
ggplot_add.seed <- function(object, plot, ...) {
    msaData <- msa_source_data(plot)
    seed_tidyData <- msa2tidy(msaData)
    seed <- object$seed
    star <- object$star

    ly <- geom_seed1(seed_tidyData, seed, star)

    msa_add(plot, ly, ...)
}



##' @method ggplot_add GCcontent
##' @export
ggplot_add.GCcontent <- function(object, plot, ...) {
    msaData <- msa_source_data(plot)
    show.legend <- object$show.legend
    GC_tidyData <- msa2tidy(msaData)

    ly <- geom_GC1(GC_tidyData, show.legend = show.legend )

    msa_add(plot, ly, ...)
}


##' @importFrom ggplot2 facet_wrap
##' @importFrom ggplot2 ggplot_add
##' @importFrom ggplot2 scale_x_continuous
##' @importFrom ggplot2 coord_cartesian
##' @importFrom ggplot2 geom_blank
##' @method ggplot_add facet_msa
##' @export
ggplot_add.facet_msa <- function(object, plot, ...){
    ## geom_msaBar() hands back a stack of panels; each panel that holds
    ## alignment data is split with the same field, so the conservation bar
    ## keeps the columns it belongs to (#49).
    if (inherits(plot, "patchwork")) {
        for (panel in seq_along(plot)) {
            current <- plot[[panel]]
            data <- msa_source_data(current)
            if (inherits(current, "gg") && is.data.frame(data) &&
                    "position" %in% names(data)) {
                plot[[panel]] <- ggplot_add(object, current, ...)
            }
        }
        return(plot)
    }

    msaData <- msa_source_data(plot)
    field <- object$field
    origin <- min(msaData$position)
    facetData <- facet_data(msaData, field)

    ## Every layer carries its own slice of the alignment (highlight boxes,
    ## annotation geoms, ...), so each one is faceted independently rather
    ## than being overwritten positionally.
    plot$layers <- lapply(plot$layers, function(ly) {
        d <- ly$data
        if (is.data.frame(d) && "position" %in% names(d)) {
            ly$data <- facet_data(d, field, origin = origin)
        }
        ly
    })

    plot$ggmsa_data <- facetData
    ## a geom_msaBar() added later has to reuse this width to stay aligned (#72)
    plot$ggmsa_field <- field

    region <- diff(range(facetData$position))
    xl_scale <- facet_scale(facetData, field)

    if (region %% field == 0) {
        plot + facet_wrap(.~facet, ncol = 1, scales = "free_x") +
            scale_x_continuous(expand = c(0,0), 
                               breaks = xl_scale, 
                               labels = xl_scale) +
            coord_cartesian()
    }else {
        max_pos <- facetData$position %>% max
        min_pos <- facetData$position %>% min
        max_facet <- facetData$facet %>% max
        minpos_maxfacet <- facetData[facetData$facet == 
                                         max_facet,"position"] %>% min
        expand_pos <-  (region %/% field + 1) * field + min_pos

        dummy <- data.frame(x = c(minpos_maxfacet, expand_pos), 
                            facet = max_facet)
        plot +
            facet_wrap(.~facet, ncol = 1, scales = "free_x") +
            geom_blank(aes_(x = ~x), dummy, inherit.aes = FALSE) +
            scale_x_continuous(expand = c(0,0), 
                               breaks = xl_scale, 
                               labels = xl_scale) +
            coord_cartesian()
    }

}

##' @method ggplot_add msaBar
##' @importFrom aplot insert_top
##' @importFrom aplot as.patchwork
##' @importFrom patchwork wrap_plots
##' @importFrom ggplot2 coord_cartesian
##' @export
ggplot_add.msaBar <- function(object, plot, ...){
    msaData <- msa_source_data(plot)
    bar_tidyData <- msa2tidy(msaData)

    p_bar <- ggplot() + ly_bar(bar_tidyData) + bar_theme(bar_tidyData)
    if ("facet" %in% names(msaData)) {
        ## facet_msa() already ran: the bar has to be split the same way (#72).
        ## insert_top() can only compose single panel plots, it keeps the first
        ## panel of a faceted one and drops the rest.
        p_bar <- ggplot_add(facet_msa(field = plot$ggmsa_field), p_bar, ...)
        return(wrap_plots(plot, p_bar, ncol = 1, heights = c(3, 1)))
    }
    plot <- plot + coord_cartesian()
    ## an <aplot> composition is inert: ggplot2 4.x finds no `+` method for it,
    ## so `plot + theme(...)` silently returns NULL. The patchwork underneath
    ## keeps the alignment aplot computed and stays composable (#49).
    insert_top(p_bar, plot, height = 3) %>% as.patchwork()
}


##' @method ggplot_add nucleotideeHelix
##' @export
ggplot_add.nucleotideeHelix <- function(object, plot, ...){
    msa_data <- msa_source_data(plot)
    tidy_data <- msa2tidy(msa_data)
    seq_numbers <- levels(tidy_data$name) %>% length

    helix_data <- object$helix_data
    color_by <- object$color_by
    overlap <- object$overlap

    if(is.data.frame(helix_data)) {
        helix_tidy <- tidy_helix(helix_data, color_by = color_by)
    }else {
        helix_tidy <- tidy_list_helix(helix_data, color_by = color_by)
    }
    ly <- layer_helix(helix_data = helix_tidy, 
                      overlap = overlap, 
                      seq_numbers = seq_numbers)
    msa_add(plot, ly, ...)
}
